#!/usr/bin/env python3
"""Generate the pre-capital blueprint views from canonical CSV data (Sprint 22). Invents nothing: every number-bearing input is UNKNOWN until a real input arrives.
Writes docs/BUSINESS-MODEL-CONTROL.md, docs/PRODUCT-BIBLE.md, docs/OPERATING-BLUEPRINT.md, docs/BLUEPRINT-STATUS.md, docs/INVESTOR-DATA-ROOM.md and website/data/investor.json.
  python3 tools/blueprint_views.py           write       python3 tools/blueprint_views.py --check   exit 1 if any output is stale or a data-room path is missing"""
import csv, json, os, re, sys
R = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(R, "tools"))
def p(*a): return os.path.join(R, *a)
def rows(f): return list(csv.DictReader(open(p(f), encoding="utf-8")))
def dat(n): return rows("docs/company/data/" + n)
def cell(s, n=170):
    s = (s or "").replace("|", "/").replace("\n", " ").strip(); return s if len(s) <= n else s[: n - 1].rsplit(" ", 1)[0] + "..."
def table(hdr, body): return ["| " + " | ".join(hdr) + " |", "|" + "---|" * len(hdr)] + ["| " + " | ".join(r) + " |" for r in body]
import fin_model, kitchen_capacity
sb = open(p("docs/readiness/VALIDATION-SCOREBOARD.md"), encoding="utf-8").read()
m = re.search(r"\*\*Total \(of 95\)\*\* \| \*\*(\d+) = (\d+)%\*\* \| \*\*(\d+) = (\d+)%\*\*", sb)
if not m: sys.exit("blueprint_views: cannot read scores")
DESIGN, EVID = m.group(1), m.group(3)
ERR = []
LANE = f"Lane B (digital planning). Evidence stays {EVID}/95 and design {DESIGN}/95: digital work never raises physical evidence."
OUT = {}

# ------------------------------------------------------------------ BUSINESS MODEL CONTROL
chain, inputs, formats, ivalue, gates, down = (dat(n) for n in ("bm-chain.csv", "bm-inputs.csv", "bm-formats.csv", "bm-info-value.csv", "bm-gates.csv", "bm-downside.csv"))
drivers, scale, paths, port, quest, supply, meas, dn, rank = (dat(n) for n in ("bm-core5-drivers.csv", "bm-brewery-scale.csv", "bm-beer-paths.csv", "bm-beer-portfolio.csv", "bm-questions.csv", "bm-supply-risk.csv", "bm-measurements.csv", "bm-data-needs.csv", "bm-real-input-rank.csv"))
req_cover = {k for k in fin_model.REQ if k not in {i["fin_model_id"] for i in inputs}}
if req_cover: ERR.append("fin_model required ids with no registry input: " + ", ".join(sorted(req_cover)))
res = fin_model.run_all()
areas = []
for i in inputs:
    if i["area"] not in areas: areas.append(i["area"])
L = ["# NASHA business model control system (generated by tools/blueprint_views.py; do not hand-edit)", "",
     "**DECISION MODEL, NOT A FORECAST, NOT A PITCH.** " + LANE + " Every financial input is UNKNOWN today and carries a provenance class; nothing here is a revenue, cost, margin, demand or professional figure. Founder direction D-81: the pre-capital phase builds this model and its input pipeline at zero cost; real inputs arrive through Session 1 and later pilots.", "",
     "## Provenance classes (one vocabulary for fin_model.py and food_costing.py)", "",
     *table(["Class", "Grade", "May feed"], [["ACTUAL, SUPPLIER_QUOTE", "A", "decision-grade output"], ["PROFESSIONAL_ESTIMATE, PUBLIC_PRIMARY", "B", "reference ranges, labelled"], ["PUBLIC_SECONDARY, RETAIL_RECEIPT, FOUNDER_ASSUMPTION, MODEL_ASSUMPTION", "C", "scenarios only; never presented as investor-grade"], ["UNKNOWN, blank, unrecognised", "excluded", "never enters a calculation"], ["TEST_FIXTURE", "excluded", "selftests only; never NASHA economics"]]),
     "", "Every output reports the weakest grade of the inputs that produced it (`input_grade`); `investor_grade` is true only when every input is grade A.", "",
     "## The chain (restaurant and brewery)", ""]
for c in ("RESTAURANT", "BREWERY"):
    L += [f"**{c}**", ""] + table(["#", "Node", "Relationship", "Real source that fills it", "Tool"], [[r["step"], f"**{r['node']}**", cell(r["relationship"], 110), cell(r["real_source_that_fills_it"], 80), cell(r["tool"], 60)] for r in chain if r["chain"] == c]) + [""]
L += ["## Input registry (what must become known; values live in `ops/finance/assumptions.csv` and `ops/finance/dish-economics.csv`, all UNKNOWN)", "",
      *table(["Area", "Inputs", "Examples"], [[a, str(sum(i["area"] == a for i in inputs)), cell(", ".join(i["input_id"] for i in inputs if i["area"] == a)[:150], 150)] for a in areas]),
      "", f"{len(inputs)} inputs in `docs/company/data/bm-inputs.csv` (each names the real input that would fill it). Waste is split so R&D waste (`waste_rd`) is never confused with steady-state waste. Customer metrics separate INTENT (`cust_return_intent`) from BEHAVIOR (`cust_repeat_rate`).", "",
      "Model status from `python3 tools/fin_model.py`: " + "; ".join(f"{k} {v['status']}" for k, v in res.items()) + ". Nothing runs because no real input exists.", "",
      "## Dish economics pipeline (Chicken 65 Totopos first; same for all Core 5)", "",
      "`python3 tools/food_costing.py economics` reports, per dish, four separate layers and never blends them:", "",
      "1. PURCHASE COST (quantity x price paid, before yield)  2. USABLE INGREDIENT COST / FOOD COST per portion (yield, trim and waste applied; frying-oil allocation from oil in minus oil out, via `oil_allocation`; sauce and garnish as recipe ingredients)  3. DIRECT VARIABLE COST (adds packaging, payment fee, direct labor minutes at a loaded wage, event cost)  4. CONTRIBUTION (price minus direct variable cost). FULL OPERATING PROFIT is a fin_model scenario, never a per-dish number.", "",
      "A retail receipt keeps the result at grade C (R&D only). A missing price, packaging, fee, labor minutes, wage or event cost leaves that layer NOT COMPUTABLE and names what unlocks it. Founder labor is priced, not zero, in mature economics. `selftest` uses TEST_FIXTURE numbers that are excluded from project economics.", "",
      "## Core 5 economic uncertainty (ranked by uncertainty, not profitability; AGENT JUDGEMENT)", ""]
L += table(["Rank", "Dish", "Cost drivers", "Yield / waste risks", "Labor", "Equipment", "Holding / portion", "Supply / volatility", "First measurement"], [[d["uncertainty_rank"], f"**{d['dish']}**", cell(d["cost_drivers"], 70), cell(d["yield_risks"] + "; " + d["waste_risks"], 110), cell(d["labor_drivers"], 60), cell(d["equipment_dependency"], 60), cell(d["holding_risk"] + " | " + d["portion_control_risk"], 90), cell(d["supply_risk"] + " | " + d["cost_volatility_inputs"], 80), cell(d["first_measurement"], 70)] for d in sorted(drivers, key=lambda x: int(x["uncertainty_rank"]))])
L += ["", "Rank reasons: " + " ".join(f"{d['dish']}: {d['rank_reason']}." for d in sorted(drivers, key=lambda x: int(x["uncertainty_rank"]))), "",
      "## Menu mix and throughput (MODEL_ASSUMPTION scenarios; not predicted guest behavior)", "",
      "Mix weights come from `ops/kitchen/capacity-assumptions.json`; every station number there is an ASSUMPTION range. The lower-bound clear time implies an UPPER bound on orders per 15 minutes; real ticket times are longer. Ingredient demand, prep demand, waste and contribution per mix are NOT COMPUTABLE until recipe quantities, yields and prices are real.", ""]
A = kitchen_capacity.load(p("ops/kitchen/capacity-assumptions.json")); body = []
for r in kitchen_capacity.run(A, trials=400):
    if r["N"] == 20: body.append([r["mix"], r["base_bottleneck"], str(round(r["base_minutes"])), str(round(r["N"] * 15 / r["base_minutes"])), cell(", ".join(f"{k} {round(v)}" for k, v in r["base_all"].items()), 90)])
L += table(["Mix (20 simultaneous orders)", "Base-case bottleneck", "Min to clear (rounded ASSUMPTION lower bound)", "Orders/15 min (rounded ASSUMPTION upper bound)", "Minutes by station"], body)
L += ["", "The measurements that matter most: station minutes per plate (fryer, comal, char, pass, cooks), measured ticket time, and the real mix. Everything else is second-order until those exist.", "",
      "## Measurements to collect during food R&D (operational observation, separate from the frozen D-74 sensory protocol)", ""]
L += table(["Measurement", "Why", "When / how", "D-74 bias risk", "Verdict"], [[cell(x["measurement"], 60), cell(x["why_it_matters_economically"], 70), cell(x["when"] + "; " + x["how_non_intrusive"], 80), cell(x["bias_risk_to_d74_sensory_protocol"], 70), x["verdict"]] for x in meas])
L += ["", "Rule: if collecting a metric could bias D-74, it is deferred. D-74 itself is untouched.", "",
      "## MVP format comparator (no values; the question is: what is the cheapest format that answers the next important question?)", ""]
L += table(["Format", "Capital categories", "Fixed / variable cost categories", "Staffing", "Permits", "Complexity", "Learning", "Reversibility", "Beer", "Max loss exposure", "Cheapest question it answers"], [[f"**{f['name']}**", cell(f["capital_categories"], 60), cell(f["fixed_cost_categories"] + " / " + f["variable_cost_categories"], 90), cell(f["staffing"], 40), cell(f["permit_dependencies"], 80), f["operating_complexity"], cell(f["learning_value"], 60), f["reversibility"], cell(f["beer_integration"], 50), cell(f["max_loss_exposure"], 50), cell(f["cheapest_question_it_answers"], 80)] for f in formats])
L += ["", "## Information-value model (spend according to information gained)", ""]
L += table(["Decision at risk", "Cost of being wrong", "Cheapest test", "Test cost class", "Time", "Reversible", "Information gained", "Capital it unlocks"], [[cell(x["decision_at_risk"], 60), cell(x["cost_of_being_wrong"], 70), cell(x["cheapest_test"], 70), x["test_cost_class"], x["time_class"], x["reversibility"], cell(x["information_gained"], 70), cell(x["next_capital_unlocked"], 40)] for x in ivalue])
L += ["", "## Capital and stop-loss gates (none has passed)", ""]
L += table(["Gate", "Commitment", "Required inputs", "Owner", "Pass", "Hold", "Fail", "Capital protected", "Stop statement"], [[g["gate_id"], cell(g["commitment"], 50), cell(g["required_inputs"], 90), cell(g["decision_owner"], 40), cell(g["pass"], 60), cell(g["hold"], 50), cell(g["fail"], 60), cell(g["capital_protected"], 40), f"**{g['stop_statement']}**"] for g in gates])
L += ["", "## Downside cases (probabilities NOT ESTIMATED)", ""]
L += table(["Case", "Mechanism", "First visible signal", "Reversible costs", "Irreversible costs", "Gate"], [[d["case"], cell(d["mechanism"], 60), cell(d["first_visible_signal"], 60), cell(d["reversible_costs"], 50), cell(d["irreversible_costs"], 70), d["protecting_gate"]] for d in down])
L += ["", "## Break-even framework (arithmetic only; not run on UNKNOWN data)", "",
      "Contribution per cover = average check minus (COGS mix + payment fees + other per-cover cost). Event-level break-even = event fixed cost / contribution per cover (`fin_model.event_breakeven`). Monthly break-even covers per open day = monthly fixed cost / (contribution per cover x open days) (`fin_model.breakeven_covers`). **Every run compares break-even covers with the physical ceiling (`max_covers_per_day`) and prints `WARNING` when break-even exceeds capacity** (`capacity_warning`). Fixed lines excluded from EBITDA: debt service and depreciation. Brewery side: `fin_model.brewery_capacity` = fermenter volume x turns per year x utilization (fermenter-limited upper bound only).", "",
      "## Brewery economic logic (questions a qualified brewer and later vendor quotes must answer; no prices)", ""]
L += table(["Scale", "Demand that must exist", "Distribution", "Utilization that matters", "Labor / space", "Oversizing fails by", "Undersizing fails by"], [[f"**{s['scale']}**", cell(s["demand_that_would_need_to_exist"], 60), cell(s["distribution_assumption_required"], 50), cell(s["tank_utilization_that_matters"], 50), cell(s["labor_change"] + " / " + s["space_change"], 60), cell(s["oversizing_failure_mode"], 50), cell(s["undersizing_failure_mode"], 50)] for s in scale])
L += ["", "The historical ~50 bbl concept is NOT a default; vessel and brewhouse size come from a brewer's variety and tank-turn analysis. Scale ladder source: `beer/BREWERY-SCALE-DECISION-FRAMEWORK.md` (agent planning aid). A forum rule of thumb (T1, not a benchmark): annual output is about brewhouse bbl x brews per week x ~50, and fermenter count follows from output / (brewhouse bbl x turns per year).", "",
      "## Make or partner (no recommendation without legal and brewer input; most optionality = rank 1)", ""]
L += table(["Path", "Brand / recipe control", "Capital", "Learning", "Speed", "Legal dependency", "Pairing", "Future migration", "Optionality rank"], [[f"{x['path']}. {x['description']}", f"{x['brand_control']} / {x['recipe_control']}", x["capital"], x["learning"], x["speed"], cell(x["legal_dependency"], 70), x["pairing_capability"], cell(x["future_migration"], 40), x["optionality_rank"]] for x in paths])
L += ["", "Optionality ranking is AGENT JUDGEMENT. Texas contract brewing and alternating proprietorship exist as arrangements with licence requirements for the parties (T1 web summary of TABC and bill text, 2026-10-11: capitol.texas.gov HB 3307 analysis; a newer bill HB 4463 outcome NOT confirmed): LEGAL REVIEW REQUIRED.", "",
      "## Core 5 beer portfolio economics (style knowledge only; every process decision is the brewer's)", ""]
L += table(["Beer", "Yeast implication", "Fermentation / conditioning", "Tank occupancy", "Quality sensitivity", "Seasonality", "Draft-velocity risk", "Redundancy", "NASHA brewer decision"], [[f"**{b['beer']}**", cell(b["yeast_family_implication"], 50), cell(b["fermentation_and_conditioning"], 70), b["tank_occupancy_class"], cell(b["quality_sensitivity"], 40), cell(b["seasonality"], 30), cell(b["draft_velocity_risk"], 50), cell(b["portfolio_redundancy_note"], 40), cell(b["nasha_brewer_decision"], 40)] for b in port])
L += ["", "Sources: BYO (Brew Your Own) German pils and weissbier pages via web search 2026-10-11, tier T1 (summaries only; official BJCP numbers were not retrieved, so no style number is quoted); homebrew schedules are examples, not NASHA process.", "", "## Open business questions (Mexican-Style Lager vs Pilsner, NA, menu mix)", ""]
L += table(["Topic", "Question", "Decision it enables", "Real input"], [[q["topic"], cell(q["question"], 100), cell(q["decision_it_enables"], 50), q["real_input"]] for q in quest])
L += ["", "## Supply-chain economic risk (AGENT JUDGEMENT from specifications; no vendor reliability is claimed)", ""]
L += table(["Item", "Single source", "Seasonal", "Import", "Price volatility", "Min order", "Spoilage", "Substitution", "D-54", "Cultural identity"], [[f"**{s['item']}**"] + [cell(s[k], 50) for k in ("single_source", "seasonal", "import", "price_volatility", "minimum_order", "spoilage", "substitution", "d54", "cultural_identity")] for s in supply])
L += ["", "## Real inputs ranked by uncertainty removed (computed)", "",
      "The listed order is the agent's judgement. Beside it, two plain counts are shown: how many registry inputs the real input fills, and how many gates list it as required. No weighting is applied.", ""]
sc = []
for r in rank:
    n_in = sum(i["collected_from"] == r["input_id"] for i in inputs); n_g = sum(r["input_id"] in g["required_inputs"] for g in gates)
    sc.append((r, n_in, n_g, n_in + 3 * n_g))
L += table(["Listed #", "Real input", "Horizon", "Cost class", "Inputs filled", "Gates fed", "What it removes"], [[str(k), r["real_input"], r["horizon"], r["cost_class"], str(a), str(b), cell(r["what_it_removes"], 80)] for k, (r, a, b, c) in enumerate(sc, 1)])
L += ["", "Reading: Horizon A inputs (Session 1 receipts, yields, labor, sensory result) are free and fill the largest block of dish-level inputs; professional and sales-based inputs remove the largest business-level uncertainty but are Horizon B/C. The founder action board therefore keeps the cook first.", "",
      "## What real data answers each Sprint 22 question", ""]
L += table(["Question", "Real inputs needed", "Unlocks", "Cheapest test before capital", "Stop / change signal"], [[cell(d["question"], 70), cell(d["real_inputs_needed"], 80), cell(d["model_outputs_it_unlocks"], 70), cell(d["cheapest_test_before_capital"], 80), cell(d["stop_or_change_signal"], 70)] for d in dn])
L += ["", "Site economics, flagship architecture, labor roles, inventory, waste, customer metrics and NA economics are carried as registry inputs (areas SITE, FLAGSHIP, LABOR, INVENTORY, WASTE, CUSTOMER, NA, BREWERY) with the format that needs each and the real input that fills it; none is populated.", ""]

bcust, bocc, bprice, brank, bsub, bcp, bcs = (dat(n) for n in ("bp-customers.csv", "bp-occasions.csv", "bp-pricing.csv", "bm-driver-rank.csv", "bp-substitutes.csv", "bp-critical-path.csv", "bp-concept-guardrails.csv"))
L += ["", "## Customer hypotheses (not personas; no guest has been studied)", ""]
L += table(["Segment", "Why they might care", "What could turn them off", "Test that shows whether they matter", "Evidence today"], [[f"**{x['segment']}**", cell(x["why_they_might_care"], 110), cell(x["what_could_turn_them_off"], 110), cell(x["test_that_shows_if_they_matter"], 100), x["evidence_today"]] for x in bcust])
L += ["", "## Occasion hypotheses (which occasions best fit; none proven)", ""]
L += table(["Occasion", "Fit with the concept", "What it requires", "Behavior that would prove it", "Priority"], [[f"**{x['occasion']}**", cell(x["fit_with_concept"], 100), cell(x["what_it_requires"], 90), cell(x["future_behavior_that_would_prove_it"], 100), x["priority_hypothesis"]] for x in bocc])
L += ["", "## Substitutes (by the job the guest hires them for)", ""]
L += table(["Substitute", "Job", "Why a guest might choose it", "What NASHA must offer instead", "Unknown"], [[f"**{x['substitute']}**", cell(x["job_the_guest_hires_it_for"], 70), cell(x["why_a_guest_might_choose_it_over_NASHA"], 80), cell(x["what_NASHA_must_offer_that_it_does_not"], 100), cell(x["what_we_do_not_know"], 80)] for x in bsub])
L += ["", "## Price logic (rules only; no prices exist)", ""] + table(["Rule", "Why", "Evidence needed first", "Test"], [[cell(x["rule"], 100), cell(x["why"], 90), cell(x["evidence_needed_before_a_price_exists"], 90), cell(x["test"], 90)] for x in bprice])
L += ["", "## Which unknowns swing the model most (structural, not dollars)", ""] + table(["Driver", "Why it swings the model", "Structure of the effect", "First real input"], [[f"**{x['driver']}**", cell(x["why_it_swings_the_model"], 90), cell(x["structure_of_the_effect"], 100), cell(x["first_real_input"], 80)] for x in brank])
L += ["", "## Critical path (durations UNKNOWN)", ""] + table(["Step", "Depends on", "Who decides", "Duration", "Evidence that unlocks it"], [[f"**{x['step']}**", cell(x["depends_on"], 80), cell(x["who_decides"], 50), x["duration"], cell(x["what_evidence_unlocks_it"], 80)] for x in bcp])
L += ["", "## Concept guardrails (what NASHA is not, what survives downsizing)", ""] + table(["Kind", "Item", "Note"], [[x["kind"], cell(x["item"], 90), cell(x["note"], 100)] for x in bcs if x["kind"] != "GLOSSARY"])
OUT["docs/BUSINESS-MODEL-CONTROL.md"] = "\n".join(L)

# ------------------------------------------------------------------ OPERATING BLUEPRINT
ops, gj, kit, brw, twin = (dat(n) for n in ("bp-operations.csv", "bp-guest-journey.csv", "bp-kitchen.csv", "bp-brewery.csv", "bp-twin-spaces.csv"))
L = ["# NASHA operating, kitchen, brewery, guest and digital-twin blueprint (generated by tools/blueprint_views.py; do not hand-edit)", "",
     "**PROPOSED OPERATING MODEL - NOT FIELD VALIDATED. REQUIREMENTS FOR FUTURE PROFESSIONAL DESIGN - NOT A DESIGN. CONCEPTUAL / ILLUSTRATIVE - VISION MODEL, NOT ARCHITECTURAL APPROVAL.** " + LANE + " No site, square footage, equipment brand, tank count, code compliance, permit or approval is claimed anywhere below. Agent-drafted from repository documents; no food-safety, alcohol-law, architectural or brewing professional has reviewed any of it.", "",
     "## 1. Operating blueprint (PROPOSED OPERATING MODEL - NOT FIELD VALIDATED)", ""]
L += table(["Area", "Proposed practice", "Controls / checks", "Owner role", "Open question", "Professional review required"], [[f"**{o['area']}**", cell(o["proposed_practice"], 200), cell(o["controls_or_checks"], 180), cell(o["owner_role"], 40), cell(o["open_question"], 140), cell(o["professional_review_required"], 60)] for o in ops])
L += ["", "## 2. Kitchen blueprint (derived from the Core 5 menu)", ""]
L += table(["Element", "Derived from", "Requirement for a future architect or chef", "Hazard / control", "Open question", "Professional"], [[f"**{k['element']}**", cell(k["derived_from_menu"], 80), cell(k["requirement_for_future_architect_or_chef"], 160), cell(k["hazard_or_control"], 120), cell(k["open_question"], 90), cell(k["professional_review_required"], 50)] for k in kit])
L += ["", "## 3. Brewery blueprint (requirements; tank size and count are NOT fixed)", ""]
L += table(["Element", "What the future design must answer", "Depends on", "Scale sensitivity", "Interaction with food and guests", "Professional"], [[f"**{b['element']}**", cell(b["what_the_future_design_must_answer"], 170), cell(b["depends_on"], 60), cell(b["scale_sensitivity"], 70), cell(b["interaction_with_food_and_guests"], 100), cell(b["professional_review_required"], 50)] for b in brw])
L += ["", "## 4. Guest experience blueprint (PROPOSED - NOT FIELD VALIDATED)", ""]
L += table(["Stage", "Guest goal", "Design principle", "Guest experiences", "Staff behavior", "Avoid", "Recovery"], [[f"**{g['stage']}**", cell(g["guest_goal"], 60), cell(g["design_principle"], 100), cell(g["what_the_guest_experiences"], 120), cell(g["staff_behavior"], 100), cell(g["failure_to_avoid"], 80), cell(g["recovery_if_it_goes_wrong"], 80)] for g in gj])
L += ["", "## 5. Architectural digital twin (CONCEPTUAL / ILLUSTRATIVE)", ""]
L += table(["Space", "Intent", "Adjacency and flow", "Day vs night", "Family / accessibility intent", "Must not be claimed"], [[f"**{t['space']}**", cell(t["intent"], 110), cell(t["adjacency_and_flow"], 90), cell(t["day_vs_night"], 70), cell(t["family_and_accessibility_intent"], 80), cell(t["must_not_be_claimed"], 60)] for t in twin])
L += ["", "Renders elsewhere in the repository are concept illustrations. They are not plans, not engineered and not evidence. Do not generate further Chicken 65 concept images before the physical prototype.", ""]

food = rows("food/CORE5-FOOD-MATRIX.csv")
def secs(L, title, banner, hdr, body, note=None):
    L += ["", f"## {title}", ""]
    if banner: L += [f"**{banner}**", ""]
    L += table(hdr, body)
    if note: L += ["", note]
bar, qc, svc, dpt, tko, acc, sus, inc, con = (dat(n) for n in ("bp-bar.csv", "bp-qc.csv", "bp-service.csv", "bp-dayparts.csv", "bp-takeout.csv", "bp-accessibility.csv", "bp-sustainability.csv", "bp-incidents.csv", "bp-continuity.csv"))
menu_, cx, sup_, col, tech, kpi, fsf, adj = (dat(n) for n in ("bp-menu.csv", "menu-complexity.csv", "bp-supply-consolidation.csv", "bp-collisions.csv", "bp-tech.csv", "bp-kpi.csv", "bp-foodsafety.csv", "bp-adjacency.csv"))
secs(L, "6. Bar blueprint", "REQUIREMENTS FOR FUTURE PROFESSIONAL DESIGN - NOT A DESIGN (no equipment, staffing or code claims)", ["Element", "Requirement", "Depends on", "Interaction", "Hazard / control", "Open question", "Professional"], [[f"**{x['element']}**", cell(x["requirement_for_future_design"], 150), cell(x["depends_on"], 50), cell(x["interaction_with_kitchen_brewery_guests"], 100), cell(x["hazard_or_control"], 100), cell(x["open_question"], 90), cell(x["professional_review_required"], 50)] for x in bar])
secs(L, "7. Food safety planning framework", "PLANNING FRAMEWORK - PROFESSIONAL/REGULATORY REVIEW REQUIRED. Not HACCP-approved, not health-department approved, not code compliant, not professionally reviewed. Sources are web-search summaries (T1); no page was opened in full and edition conflicts are noted.", ["Topic", "Planning point", "Control idea", "Source (T1)", "Limitation"], [[f"**{x['topic']}**", cell(x["planning_framework_point"], 130), cell(x["key_control_idea"], 130), cell(x["authoritative_source"] + (" " + x["source_url"] if x["source_url"] else ""), 120), cell(x["limitation"], 110)] for x in fsf], "Any numeric limit appears only where a source summary stated it, and must be confirmed with the authority. The agent-proposed 60 C hot-hold floor in the Session 1 sheet stays unconfirmed until reconciled with the authority's figure.")
secs(L, "8. Quality system (what must stay consistent; R&D acceptance is separate from future production QC)", None, ["Domain", "What must be consistent to feel like NASHA", "R&D acceptance (decided by tests now)", "Future production QC (light)", "Owner", "Evidence trigger"], [[f"**{x['domain']}**", cell(x["what_must_be_consistent_to_feel_like_NASHA"], 120), cell(x["rd_acceptance_criteria"], 130), cell(x["future_production_qc"], 120), cell(x["owner_role"], 40), cell(x["evidence_trigger"], 80)] for x in qc])
cx_dims = ["unique_skus", "prep_stages", "station_count", "cook_time", "holding_sensitivity", "special_equipment", "waste", "training_burden"]
cxrows = []
for x in cx:
    vals = {k: int(x[k]) for k in cx_dims}; top = [k.replace("_", " ") for k, v in vals.items() if v == max(vals.values())]
